type N = {v:number,l:N|null,r:N|null};
function tree(a:(number|null)[]):N|null { if(!a.length||a[0]===null)return null; const root:N={v:a[0],l:null,r:null};const q:N[]=[root];let j=1;for(let i=0;i<q.length&&j<a.length;i++){for(const side of ['l','r'] as const){const v=a[j++];if(v!==null&&v!==undefined){const n:N={v,l:null,r:null};q[i][side]=n;q.push(n);}}}return root;}
export function widthOfBinaryTree(values: (number|null)[]): number {
const root=tree(values);if(!root)return 0;let q:{node:N,index:number}[]=[{node:root,index:0}],best=0;while(q.length){best=Math.max(best,q[q.length-1].index-q[0].index+1);const base=q[0].index,next:{node:N,index:number}[]=[];for(const {node,index} of q){const p=index-base;if(node.l)next.push({node:node.l,index:2*p});if(node.r)next.push({node:node.r,index:2*p+1});}q=next;}return best;
}
